import React from 'react';
import { 
  Box, Card, CardContent, Typography, Divider, Grid, 
  LinearProgress, Paper, Chip
} from '@mui/material';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import ReportProblemIcon from '@mui/icons-material/ReportProblem';
import ChatIcon from '@mui/icons-material/Chat';
import PersonIcon from '@mui/icons-material/Person';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import WarningIcon from '@mui/icons-material/Warning';
import MessageIcon from '@mui/icons-material/Message';
import HeadsetMicIcon from '@mui/icons-material/HeadsetMic';

// Component for displaying a statistic card
const StatCard = ({ title, value, icon, color, subtitle }) => (
  <Paper
    elevation={1}
    sx={{
      p: 2,
      display: 'flex',
      flexDirection: 'column',
      height: '100%',
      borderLeft: 3,
      borderColor: `${color}.main`,
    }}
  >
    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
      <Typography variant="subtitle2" component="div" gutterBottom sx={{ fontWeight: 'medium' }}>
        {title}
      </Typography>
      <Box sx={{ color: `${color}.main` }}>{icon}</Box>
    </Box>
    <Typography variant="h5" component="div" sx={{ fontWeight: 'bold', my: 1, color: `${color}.main` }}>
      {value}
    </Typography>
    <Typography variant="caption" color="text.secondary">
      {subtitle}
    </Typography>
  </Paper>
);

// Add custom text style
const textStyle = {
  color: 'var(--text-color)',
  fontSize: '1.1rem'
};

const SummaryStats = ({ analyzedData }) => {
  const { chunks, complaintPercentage, utterances } = analyzedData;

  // Additional statistics
  const totalUtterances = utterances.length;
  const callerUtterances = utterances.filter(u => u.speaker === 'caller').length;
  const agentUtterances = utterances.filter(u => u.speaker === 'agent').length;

  const complaintChunks = chunks.filter(chunk => chunk.isComplaint).length;
  const totalChunks = chunks.length;

  // Complaint utterances (just for display - we actually analyze at chunk level)
  const callerComplaintUtterances = Math.round(callerUtterances * (complaintPercentage / 100));

  // Severity calculation based on complaint percentage
  let severity = 'Low';
  let severityColor = 'success';

  if (complaintPercentage >= 70) {
    severity = 'High';
    severityColor = 'error';
  } else if (complaintPercentage >= 30) {
    severity = 'Medium';
    severityColor = 'warning';
  }

  // Get timestamp information
  let earliestTimestamp = null;
  let latestTimestamp = null;

  if (chunks && chunks.length > 0) {
    // Find chunks with timestamps
    const chunksWithTimestamps = chunks.filter(chunk => chunk.timestamp);

    if (chunksWithTimestamps.length > 0) {
      // Find earliest and latest timestamps
      earliestTimestamp = new Date(Math.min(...chunksWithTimestamps.map(c => new Date(c.timestamp))));
      latestTimestamp = new Date(Math.max(...chunksWithTimestamps.map(c => new Date(c.timestamp))));
    }
  }

  // Calculate metrics for System Diagnostics section
  const averagePercentage = complaintPercentage.toFixed(1);

  // Find peak window (window with highest complaint percentage)
  let peakWindow = "NONE";
  let runtime = "00:00";

  if (chunks && chunks.length > 0) {
    let maxPercentage = 0;
    let maxWindow = "NONE";

    // Process chunks to create data for the chart
    const data = [];
    let currentIndex = 0;

    chunks.forEach((chunk, index) => {
      // Skip chunks without messages
      if (!chunk.messages || chunk.messages.length === 0) return;

      currentIndex++;
      const windowName = `W${currentIndex}`;
      const complaintLevel = chunk.complaint ? (chunk.complaint_level === "high" ? 2 : 1) : 0;
      const complaintPct = chunk.complaint_percentage ? chunk.complaint_percentage : 0;

      if (complaintPct > maxPercentage) {
        maxPercentage = complaintPct;
        maxWindow = windowName;
      }

      // Get first and last message timestamps
      const timestamps = chunk.messages.map(msg => new Date(msg.timestamp).getTime()).filter(t => !isNaN(t));
      if (timestamps.length > 0) {
        const startTime = new Date(Math.min(...timestamps));
        const endTime = new Date(Math.max(...timestamps));
        const timeRange = `${startTime.toLocaleTimeString()} - ${endTime.toLocaleTimeString()}`;

        // Description based on complaint level
        let description = "Normal conversation flow";
        if (complaintLevel === 1) description = "Minor complaint signals detected";
        if (complaintLevel === 2) description = "Significant complaint markers present";

        data.push({
          window: windowName,
          timeRange,
          complaintLevel,
          complaintPercentage: complaintPct,
          description
        });
      }
    });

    peakWindow = maxWindow;

    // Calculate runtime if timestamps are available
    if (earliestTimestamp && latestTimestamp) {
      const timeDiff = Math.abs(latestTimestamp - earliestTimestamp);
      const minutes = Math.floor(timeDiff / (1000 * 60));
      const seconds = Math.floor((timeDiff % (1000 * 60)) / 1000);
      runtime = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    }
  }

  // Define cyberpunk colors for consistency with ComplaintTrackingChart
  const colors = {
    dark: {
      base: '#000000',
      secondary: '#0a1a0a'
    },
    neon: {
      green: '#00ff41',
      darkGreen: '#00802b',
      brightGreen: '#80ff00',
      yellow: '#f9f871',
      red: '#ff416c'
    },
    text: {
      primary: '#ffffff',
      secondary: '#7a8c7a'
    }
  };

  return (
    <Card variant="outlined" sx={{ mb: 4 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom sx={{ ...textStyle, fontSize: '1.3rem !important' }}>
          Analysis Summary
        </Typography>

        <Typography variant="body2" paragraph sx={{ ...textStyle }}>
          Overview of complaint analysis for the conversation.
        </Typography>

        <Box sx={{ mb: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
            <Typography variant="subtitle2" sx={{ ...textStyle }}>
              Overall Complaint Level: {complaintPercentage.toFixed(1)}%
            </Typography>
            <Chip 
              label={severity}
              color={severityColor}
              size="small"
              icon={<WarningAmberIcon />}
              sx={{ color: 'var(--text-color)', '& .MuiChip-label': { fontSize: '1.1rem' } }}
            />
          </Box>
          <LinearProgress
            variant="determinate"
            value={complaintPercentage}
            color={severityColor}
            sx={{ height: 10, borderRadius: 5 }}
          />
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 0.5 }}>
            <Typography variant="caption" sx={{ ...textStyle }}>
              0% (No complaints)
            </Typography>
            <Typography variant="caption" sx={{ ...textStyle }}>
              100% (All complaints)
            </Typography>
          </Box>
        </Box>

        <Divider sx={{ my: 2 }} />

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Complaint Severity"
              value={severity}
              icon={<WarningAmberIcon />}
              color={severityColor}
              subtitle="Based on percentage"
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Complaint Chunks"
              value={`${complaintChunks}/${totalChunks}`}
              icon={<ReportProblemIcon />}
              color="error"
              subtitle={`${(complaintChunks / totalChunks * 100).toFixed(1)}% of chunks`}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Total Utterances"
              value={totalUtterances}
              icon={<ChatIcon />}
              color="info"
              subtitle={`${callerUtterances} caller, ${agentUtterances} agent`}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              title="Caller Complaints"
              value={`~${callerComplaintUtterances}/${callerUtterances}`}
              icon={<PersonIcon />}
              color="warning"
              subtitle="Estimated from chunks"
            />
          </Grid>
        </Grid>

        {earliestTimestamp && latestTimestamp && (
          <>
            <Divider sx={{ my: 2 }} />

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 2 }}>
              <AccessTimeIcon color="action" />
              <Typography 
                variant="body1" 
                sx={{ 
                  ...textStyle,
                  fontFamily: 'monospace',
                  fontWeight: 'medium' 
                }}
              >
                Analysis period: {earliestTimestamp.toLocaleTimeString()} - {latestTimestamp.toLocaleTimeString()} 
                ({((latestTimestamp - earliestTimestamp) / 1000).toFixed(1)} seconds)
              </Typography>
            </Box>
          </>
        )}

        {/* SYSTEM DIAGNOSTICS Section */}
        <Box sx={{ 
          width: '100%', 
          p: 2, 
          mt: 2, 
          borderRadius: 1, 
          bgcolor: 'rgba(0, 20, 0, 0.7)', 
          border: '1px solid rgba(0, 255, 65, 0.5)',
          boxShadow: '0 0 15px rgba(0, 128, 43, 0.5)'
        }}>
          <Typography 
            variant="subtitle1" 
            sx={{ 
              color: '#00ff41', 
              fontFamily: 'monospace', 
              fontSize: '0.875rem',
              fontWeight: 600,
              mb: 1,
              textAlign: 'center', 
              textTransform: 'uppercase',
              letterSpacing: '0.1em'
            }}
          >
            // SYSTEM DIAGNOSTICS //
          </Typography>

          <Grid container spacing={2}>
            <Grid item xs={4}>
              <Box sx={{ 
                bgcolor: '#000000', 
                p: 1, 
                borderRadius: 1, 
                border: '1px solid rgba(0, 255, 65, 0.5)',
                boxShadow: '0 0 10px rgba(0, 128, 43, 0.5)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center'
              }}>
                <Typography variant="caption" sx={{ color: '#7a8c7a', fontFamily: 'monospace', textTransform: 'uppercase' }}>
                  CMPLNT.RATIO
                </Typography>
                <Typography variant="h6" sx={{ color: '#00ff41', fontFamily: 'monospace', fontWeight: 'bold' }}>
                  {averagePercentage}%
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={4}>
              <Box sx={{ 
                bgcolor: '#000000', 
                p: 1, 
                borderRadius: 1, 
                border: '1px solid rgba(0, 255, 65, 0.5)',
                boxShadow: '0 0 10px rgba(0, 128, 43, 0.5)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center'
              }}>
                <Typography variant="caption" sx={{ color: '#7a8c7a', fontFamily: 'monospace', textTransform: 'uppercase' }}>
                  PEAK.ALARM
                </Typography>
                <Typography variant="h6" sx={{ color: '#00ff41', fontFamily: 'monospace', fontWeight: 'bold' }}>
                  {peakWindow}
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={4}>
              <Box sx={{ 
                bgcolor: '#000000', 
                p: 1, 
                borderRadius: 1, 
                border: '1px solid rgba(0, 255, 65, 0.5)',
                boxShadow: '0 0 10px rgba(0, 128, 43, 0.5)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center'
              }}>
                <Typography variant="caption" sx={{ color: '#7a8c7a', fontFamily: 'monospace', textTransform: 'uppercase' }}>
                  RUNTIME
                </Typography>
                <Typography variant="h6" sx={{ color: '#00ff41', fontFamily: 'monospace', fontWeight: 'bold' }}>
                  {runtime}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </Box>

        {/* CONVERSATION DATASTREAM Section */}
        {chunks && chunks.length > 0 && (
          <Box sx={{ width: '100%', mt: 2 }}>
            <Typography 
              variant="subtitle1" 
              sx={{ 
                color: '#00ff41', 
                fontFamily: 'monospace', 
                fontSize: '0.875rem',
                fontWeight: 600,
                mb: 1,
                textAlign: 'center', 
                textTransform: 'uppercase',
                letterSpacing: '0.1em'
              }}
            >
              // CONVERSATION DATASTREAM //
            </Typography>

            <Box sx={{ boxShadow: '0 0 15px rgba(0, 128, 43, 0.5)' }}>
              <table style={{ 
                minWidth: '100%', 
                backgroundColor: '#000000', 
                border: '1px solid rgba(0, 255, 65, 0.5)' 
              }}>
                <thead>
                  <tr style={{ backgroundColor: '#0a1a0a', borderBottom: '1px solid rgba(0, 255, 65, 0.5)' }}>
                    <th style={{ padding: '4px', borderRight: '1px solid rgba(0, 255, 65, 0.5)', fontFamily: 'monospace', fontSize: '0.75rem', color: '#00ff41' }}>SEQ</th>
                    <th style={{ padding: '4px', borderRight: '1px solid rgba(0, 255, 65, 0.5)', fontFamily: 'monospace', fontSize: '0.75rem', color: '#00ff41' }}>TIME</th>
                    <th style={{ padding: '4px', borderRight: '1px solid rgba(0, 255, 65, 0.5)', fontFamily: 'monospace', fontSize: '0.75rem', color: '#00ff41' }}>STATUS</th>
                    <th style={{ padding: '4px', fontFamily: 'monospace', fontSize: '0.75rem', color: '#00ff41' }}>DATA</th>
                  </tr>
                </thead>
                <tbody style={{ fontFamily: 'monospace' }}>
                  {chunks.map((chunk, index) => {
                    // Skip chunks without messages
                    if (!chunk.messages || chunk.messages.length === 0) return null;

                    const windowName = `W${index + 1}`;
                    const complaintLevel = chunk.complaint ? (chunk.complaint_level === "high" ? 2 : 1) : 0;
                    const complaintPct = chunk.complaint_percentage ? chunk.complaint_percentage : 0;

                    // Get first and last message timestamps
                    const timestamps = chunk.messages.map(msg => new Date(msg.timestamp).getTime()).filter(t => !isNaN(t));
                    if (timestamps.length === 0) return null;

                    const startTime = new Date(Math.min(...timestamps));
                    const endTime = new Date(Math.max(...timestamps));
                    const timeRange = `${startTime.toLocaleTimeString()} - ${endTime.toLocaleTimeString()}`;

                    // Description based on complaint level
                    let description = "Normal conversation flow";
                    if (complaintLevel === 1) description = "Minor complaint signals detected";
                    if (complaintLevel === 2) description = "Significant complaint markers present";

                    return (
                      <tr key={index} style={{ 
                        borderBottom: '1px solid rgba(0, 255, 65, 0.3)', 
                        backgroundColor: index % 2 === 0 ? '#000000' : '#0a1a0a' 
                      }}>
                        <td style={{ 
                          padding: '4px', 
                          borderRight: '1px solid rgba(0, 255, 65, 0.3)', 
                          fontFamily: 'monospace', 
                          fontWeight: 500, 
                          fontSize: '0.75rem', 
                          color: '#00ff41' 
                        }}>{windowName}</td>
                        <td style={{ 
                          padding: '4px', 
                          borderRight: '1px solid rgba(0, 255, 65, 0.3)', 
                          fontFamily: 'monospace', 
                          fontSize: '0.75rem', 
                          color: '#00802b' 
                        }}>{timeRange}</td>
                        <td style={{ padding: '4px', borderRight: '1px solid rgba(0, 255, 65, 0.3)' }}>
                          <span style={{ 
                            padding: '0 4px', 
                            fontSize: '0.75rem', 
                            fontWeight: 600, 
                            fontFamily: 'monospace',
                            backgroundColor: '#000000',
                            border: complaintLevel === 0 ? '1px solid rgba(0, 255, 65, 0.5)' : 
                                     complaintLevel === 1 ? '1px solid rgba(249, 248, 113, 0.5)' : 
                                                        '1px solid rgba(255, 65, 108, 0.5)',
                            color: complaintLevel === 0 ? '#00ff41' : 
                                   complaintLevel === 1 ? '#f9f871' : 
                                                      '#ff416c',
                            boxShadow: complaintLevel === 0 ? '0 0 5px rgba(0, 255, 65, 0.5)' : 
                                       complaintLevel === 1 ? '0 0 5px rgba(249, 248, 113, 0.5)' : 
                                                          '0 0 5px rgba(255, 65, 108, 0.5)'
                          }}>
                            {complaintLevel === 0 ? 'STABLE' : 
                             complaintLevel === 1 ? 'CAUTION' : 'ALERT'}
                          </span>
                        </td>
                        <td style={{ 
                          padding: '4px', 
                          fontFamily: 'monospace', 
                          fontSize: '0.75rem', 
                          color: '#00802b' 
                        }}>{description}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </Box>
          </Box>
        )}
      </CardContent>
    </Card>
  );
};

export default SummaryStats;
